SELECT json_extract(value, '$.route') AS route, json_extract(value, '$.selector') AS selector, json_extract(value, '$.client') AS client, json_extract(value, '$.contract') AS contract, json_extract(value, '$.caveat') AS caveat FROM json_each('[{"route": "Claude on Microsoft Foundry", "selector": "anthropic/azure/<deployment>", "client": "AsyncAnthropicFoundry", "contract": "Anthropic Messages", "caveat": "Use the Anthropic endpoint; native Claude semantics and model-specific gates."}, {"route": "OpenAI on Azure", "selector": "openai/azure/<deployment>", "client": "AsyncAzureOpenAI", "contract": "Chat Completions or Responses", "caveat": "Endpoint/API version and deployment must support the selected API."}, {"route": "Azure model inference", "selector": "azureai/<deployment>", "client": "Azure AI Inference ChatCompletionsClient", "contract": "Azure inference chat completions", "caveat": "Upstream mapped configuration is narrower than the shared config type."}, {"route": "Claude direct", "selector": "anthropic/<model>", "client": "AsyncAnthropic", "contract": "Anthropic Messages", "caveat": "Direct-only features are explicitly gated in the adapter."}, {"route": "Claude on AWS / Google", "selector": "anthropic/bedrock/<model> or anthropic/vertex/<model>", "client": "AsyncAnthropicBedrock / AsyncAnthropicVertex", "contract": "SDK adapts Messages to hosting service", "caveat": "Hosting-specific authentication and feature availability."}, {"route": "Bedrock generic", "selector": "bedrock/<model>", "client": "AWS Bedrock runtime", "contract": "Converse / ConverseStream", "caveat": "Separate adapter from anthropic/bedrock; do not equate capabilities."}, {"route": "Google models", "selector": "google/<model>", "client": "Google GenAI client", "contract": "GenerateContent", "caveat": "Contents/parts and thinking config differ from OpenAI and Claude."}, {"route": "Compatible / local servers", "selector": "openai-api/<model>, vllm/<model>, other registered providers", "client": "Provider-specific client, often OpenAI-compatible", "contract": "Advertised server API or local inference", "caveat": "Compatibility does not imply native reasoning, tools, or schema enforcement."}]');
